#!/usr/bin/env node/** * BANF Member Report Generator ΓÇö v3.0 * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ * 100% data-driven ΓÇö no hardcoded member values. * ALL data sourced from: *   ΓÇó Live CRM API    (profile, payments, communications, roles, awards) *   ΓÇó Google Drive documents / local XLSX files (Jagriti, Family Universe, *                              Membership sheets, event spreadsheets) *   ΓÇó PDF documents   (Spandan magazine, event planning docs, GBM minutes) *   ΓÇó Email threads   (evite RSVPs, article submissions, volunteer notes) *   ΓÇó Web search      (LinkedIn profile, public photo) * * Usage: *   node member-report-generator.js --memberId=MBR-MLX3JU4F-AMOZ *   node member-report-generator.js --name="Ranadhir Ghosh" *   node member-report-generator.js --memberId=MBR-... --out=my-report.html * ΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉΓòÉ */'use strict';const XLSX    = require('xlsx');const fetch   = require('node-fetch');const fs      = require('fs');const path    = require('path');const crypto  = require('crypto');const zlib    = require('zlib'); // built-in ΓÇö for PDF stream decompression// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// Config ΓÇö only infrastructure constants here, ZERO member-specific data// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst API_BASE   = 'https://banfwix.wixsite.com/banf1/_functions';const ADMIN_EMAIL = 'banfjax@gmail.com';const ADMIN_KEY  = 'IST.eyJraWQiOiJQb3pIX2FDMiIsImFsZyI6IlJTMjU2In0..GVx8jeX6lw2qF3cTWQJX4hWVs_unIkBJAgywR_sbASHyJhs95w6euuWIRW5CfQ_PSZmCKHw6ma5IpQawGhR79hYUi46_49yAg9fCklP60iJJlPLKdLj6NtOVIoYoc-WsG8nOW_9qo1om08YA-Qh_5O-oZv6oRW2gk7C2eOF5E1pjt0CgmVIRK8z5HvVqlXYftO9NtaSfHh9vhSVPkxVU6jp1OJBsR_UdcdL6Rpiv-bJx0hKJJOfNJMc89oEBiCaAJ4No65-FsGouo2yIYUCsDAQTtBk9rWh3cH8_n-ts0WK57kdtXVKRqQ5g7ch5usUdFAUBTSaviGXpExj5VoTVKQ';const DATA_ROOT  = path.join(__dirname, 'banf1-wix', 'banf-data_ingest', 'data');const API_HDRS   = { 'Content-Type': 'application/json', 'x-user-email': ADMIN_EMAIL };// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// CLI args// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇconst ARGS = process.argv.slice(2).reduce((a, s) => {  const [k, ...v] = s.replace(/^--/, '').split('=');  a[k] = v.join('=') || true;  return a;}, {});const TARGET_MEMBER_ID = ARGS.memberId || ARGS.memberid || null;const TARGET_NAME      = ARGS.name || null;const OUT_FILE         = ARGS.out || null; // auto-set after member loadedif (!TARGET_MEMBER_ID && !TARGET_NAME) {  console.error('Usage: node member-report-generator.js --memberId=MBR-... OR --name="First Last"');  process.exit(1);}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// Helpers// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇfunction norm(s) { return (s || '').toLowerCase().replace(/\s+/g, ' ').trim(); }function esc(s)  { return (s || '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;'); }function sleep(ms) { return new Promise(r => setTimeout(r, ms)); }/** * STRICT name matching ΓÇö avoids bare-surname false positives. * * Rules: * 1. Full-name match  ("Ranadhir Ghosh") ΓÇö always accepted * 2. firstName match   ("Ranadhir") ΓÇö accepted only if firstName >= 4 chars *    to avoid collisions like "Jay" matching "Jayanta" * 3. Alias match       ("Ranadhir Da/ Moumita Di") ΓÇö accepted * 4. lastName ALONE    ΓÇö NEVER accepted ("Ghosh" is too common) * * For family-level scanning use `mentionsFamily()` which IS broader. */function mentionsName(text, firstName, lastName, aliases = []) {  if (!text) return false;  const t = norm(text);  // 1. Full name (both parts)  const full = norm(`${firstName} ${lastName}`);  if (full.length > 4 && t.includes(full)) return true;  // 2. firstName alone ΓÇö must be distinctive (>= 4 chars)  if (firstName && norm(firstName).length >= 4 && t.includes(norm(firstName))) return true;  // 3. Alias list (document-derived name variants)  for (const a of aliases) {    const na = norm(a);    if (na.length >= 4 && t.includes(na)) return true;  }  return false;}/** * Build list of name aliases from co-occurrence data. * Sources: *  - Payment raw entries ("Ranadhir Da/ Moumita Di") *  - Family Universe Raw Entries / Family Members sheets *  - Jagriti comments ("Ranadhir da's daughter") *  - CRM displayName, alternateEmail */function buildAliases(member, xlsxFiles) {  const firstName = member.firstName;  const lastName  = member.lastName;  const aliases = new Set();  // From CRM fields  if (member.displayName) aliases.add(member.displayName);  if (member.email) aliases.add(member.email.split('@')[0]);  // ranadhir.ghosh  if (member.alternateEmail) aliases.add(member.alternateEmail.split('@')[0]);  // Scan XLSX for entries that contain BOTH first AND last name (co-occurrence)  for (const fp of xlsxFiles) {    let wb;    try { wb = XLSX.readFile(fp, { cellDates: true }); } catch (_) { continue; }    for (const sheetName of wb.SheetNames) {      let rows;      try { rows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], { defval: '' }); } catch (_) { continue; }      for (const row of rows) {        const rowStr = norm(JSON.stringify(row));        // Must contain firstName ΓÇö then extract the full entry as an alias        if (firstName && norm(firstName).length >= 4 && rowStr.includes(norm(firstName))) {          // Raw Entries: "Name Entry" field          const entry = row['Name Entry'] || row['Name'] || row['Contributor'] || '';          if (entry && norm(entry).includes(norm(firstName))) {            aliases.add(entry.trim());          }          // rawNameEntry from payment row          const rawName = row['rawNameEntry'] || '';          if (rawName && norm(rawName).includes(norm(firstName))) {            aliases.add(rawName.trim());          }        }      }    }  }  // Remove very short aliases and the bare lastName  const result = [...aliases].filter(a => {    const na = norm(a);    return na.length >= 4 && na !== norm(lastName);  });  return result;}/** * Detect REAL family unit members using co-occurrence evidence. * * Evidence sources (ranked by reliability): * 1. Payment entries with compound names: "Ranadhir Da/ Moumita Di" ΓåÆ Moumita is family * 2. XLSX Family Members sheet where same Family ID: FAM-2E1CEE29 ΓåÆ shared household * 3. Jagriti comments: "Ranadhir da's daughter" on Arundhuti(Rumi) ΓåÆ daughter * 4. Same-surname + same payment entry ΓåÆ likely same household * * Returns array of { name, relationship, source, confidence } */function detectFamilyUnit(firstName, lastName, xlsxFiles) {  const members = [];  const seen = new Set();  const addMember = (name, rel, src, conf) => {    const key = norm(name);    if (key.length < 2 || seen.has(key)) return;    // Skip if it's the target member themselves    if (key === norm(`${firstName} ${lastName}`) || key === norm(firstName)) return;    seen.add(key);    members.push({ name: name.trim(), relationship: rel, source: src, confidence: conf });  };  for (const fp of xlsxFiles) {    let wb;    try { wb = XLSX.readFile(fp, { cellDates: true }); } catch (_) { continue; }    const filename = path.basename(fp);    for (const sheetName of wb.SheetNames) {      let rows;      try { rows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], { defval: '' }); } catch (_) { continue; }      for (const row of rows) {        const rowStr = norm(JSON.stringify(row));        if (!firstName || norm(firstName).length < 4) continue;        if (!rowStr.includes(norm(firstName))) continue;        // Source 1: Compound payment names ΓÇö "Ranadhir Da/ Moumita Di"        const nameField = row['Name Entry'] || row['Name'] || row['Original Entry'] || '';        if (nameField && norm(nameField).includes(norm(firstName))) {          // Split on / or & or , or + or "and"          const parts = nameField.split(/[/&+,]|\band\b/i).map(p => p.trim()).filter(p => p.length > 1);          for (const part of parts) {            const pn = norm(part);            if (pn.includes(norm(firstName))) continue; // skip self            // Remove honorifics Da/Di/Dada/Didi            const cleanName = part.replace(/\b(da|di|dada|didi|uncle|aunty|auntie)\b/gi, '').trim();            if (cleanName.length >= 3 && !/^(family|and|the|with|mr|mrs|ms|dr)$/i.test(cleanName)) {              addMember(cleanName, 'Spouse/Partner', `${filename} / ${sheetName}`, 'high');            }          }        }        // Source 2: Family Members sheet ΓÇö same Family ID        // STRICT: only include members whose OWN "Original Entry" directly        // mentions the target first name. This prevents the Universe's overbroad        // FAM grouping (e.g. FAM-2E1CEE29 lumps ALL Ghosh) from adding        // unrelated households like Anirban, Dipra, Suman, etc.        if (/family member/i.test(sheetName)) {          const famId = row['Family ID'] || '';          const origEntry = norm(row['Original Entry'] || '');          if (famId && origEntry.includes(norm(firstName))) {            for (const r2 of rows) {              if (r2['Family ID'] !== famId) continue;              const r2Orig = norm(r2['Original Entry'] || '');              // The OTHER member must also come from an entry that              // mentions our target person (i.e. same compound name)              if (!r2Orig.includes(norm(firstName))) continue;              // Skip self rows ΓÇö check First Name field specifically              const r2FirstName = norm(r2['First Name'] || '');              if (r2FirstName === norm(firstName)) continue;              const fn = (r2['First Name'] || '').trim();              const ln = (r2['Last Name'] || r2['Primary Surname'] || '').trim();              const fullN = `${fn} ${ln}`.trim();              // Don't add generic/artifact entries              if (fullN.length > 2 && !['Da', 'Di', 'Family'].includes(fn)) {                addMember(fullN, 'Family Member', `${filename} / ${sheetName} (from: "${(r2['Original Entry']||'').substring(0,40)}")`, 'high');              }            }          }        }        // Source 3: Jagriti comments ΓÇö "Ranadhir da's daughter/son/wife"        const comments = row['Comments'] || row['__EMPTY'] || row['Notes'] || '';        if (comments && norm(comments).includes(norm(firstName))) {          const contributor = row['Contributor'] || row['Name'] || '';          const relMatch = comments.match(new RegExp(firstName + "[\\s']*(?:da|di|dada)?[\\s']*s?\\s*(daughter|son|wife|husband|mother|father|sister|brother|child|kid|niece|nephew)", 'i'));          const rel = relMatch ? relMatch[1] : 'Related';          if (contributor) addMember(contributor, rel.charAt(0).toUpperCase() + rel.slice(1), `${filename}: ${comments.substring(0,60)}`, 'high');        }      }    }  }  return members;}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// API functions// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function apiGet(endpoint, params = {}) {  const qs = new URLSearchParams({ ...params, admin_key: ADMIN_KEY }).toString();  const res = await fetch(`${API_BASE}/${endpoint}?${qs}`, { headers: API_HDRS });  if (!res.ok) throw new Error(`GET ${endpoint} ΓåÆ ${res.status}`);  return res.json();}/** Find member by name using crm_search_members or crm_members list */async function findMemberByName(name) {  try {    const d = await apiGet('crm_search_members', { q: name, limit: 5 });    const items = d.members || d.items || [];    if (items.length > 0) return items[0];  } catch (_) {}  // Fallback: scan all members  const all = await apiGet('crm_members', { limit: 200 });  const members = all.members || all.items || [];  const n = norm(name);  return members.find(m =>    norm(`${m.firstName} ${m.lastName}`).includes(n) ||    norm(m.displayName || '').includes(n)  ) || null;}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// PDF text extractor ΓÇö pure JS + built-in zlib// Handles both uncompressed and FlateDecode (zlib) PDF content streams// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ/** Parse PDF text from a raw string (latin1-encoded content) */function parsePdfTextFromString(str) {  const text = [];  const btBlocks = str.match(/BT[\s\S]*?ET/g) || [];  for (const block of btBlocks) {    // Tj operator    const r1 = /\(([^)\\]{0,300}(?:\\.[^)\\]{0,300})*)\)\s*Tj/g;    let m;    while ((m = r1.exec(block)) !== null) {      const v = m[1].replace(/\\n/g,' ').replace(/\\r/g,' ')        .replace(/\\\(/g,'(').replace(/\\\)/g,')').replace(/\\\\/g,'\\').trim();      if (v.length > 0) text.push(v);    }    // TJ operator    const r2 = /\[([^\]]*)\]\s*TJ/g;    while ((m = r2.exec(block)) !== null) {      const parts = m[1].match(/\(([^)\\]*(?:\\.[^)\\]*)*)\)/g) || [];      const joined = parts.map(p => p.slice(1,-1)        .replace(/\\n/g,' ').replace(/\\r/g,' ')        .replace(/\\\(/g,'(').replace(/\\\)/g,')')).join('');      if (joined.trim()) text.push(joined.trim());    }  }  return text;}function extractPdfText(buffer) {  try {    const str = buffer.toString('latin1');    let allText = [];    // Pass 1: try uncompressed streams directly    allText.push(...parsePdfTextFromString(str));    // Pass 2: find FlateDecode compressed streams and decompress them    // PDF pattern: << ... /FlateDecode ... >> stream\r\n<data>\r\nendstream    const streamRe = /stream\r?\n([\s\S]*?)\r?\nendstream/g;    let sm;    while ((sm = streamRe.exec(str)) !== null) {      const raw = Buffer.from(sm[1], 'latin1');      // Only try decompression on streams that look like zlib (starts with 0x78)      if (raw.length < 4) continue;      const b0 = raw[0], b1 = raw[1];      const isZlib = (b0 === 0x78 && (b1 === 0x9C || b1 === 0x01 || b1 === 0xDA || b1 === 0x5E));      if (!isZlib) continue;      try {        const decompressed = zlib.inflateSync(raw).toString('latin1');        allText.push(...parsePdfTextFromString(decompressed));      } catch (_) {        // Try inflate raw (no zlib header)        try {          const decompressed = zlib.inflateRawSync(raw).toString('latin1');          allText.push(...parsePdfTextFromString(decompressed));        } catch (_) {}      }    }    // Pass 3: readable ASCII fallback when no BT/ET blocks found    if (allText.length < 5) {      const ascii = str.replace(/[^\x20-\x7E\n\r\t]/g, ' ')        .replace(/\s{3,}/g, '\n').trim();      const lines = ascii.split('\n').filter(l => {        const lc = l.trim();        return lc.length > 5 && /[a-zA-Z]{3,}/.test(lc) && !/^[\d\s.()\[\]{}]+$/.test(lc);      });      allText.push(...lines.slice(0, 300));    }    return allText.join(' ').replace(/\s+/g, ' ').trim();  } catch (e) {    return '';  }}/** Walk a directory tree and return all files matching extension filter */function walkDir(dir, exts) {  const results = [];  if (!fs.existsSync(dir)) return results;  for (const entry of fs.readdirSync(dir)) {    const full = path.join(dir, entry);    const stat = fs.statSync(full);    if (stat.isDirectory()) {      results.push(...walkDir(full, exts));    } else if (exts.some(ext => entry.toLowerCase().endsWith(ext))) {      results.push(full);    }  }  return results;}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// Classify a communication email// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇfunction classifyEmail(email) {  const subj = norm(email.subject || '');  const body = norm(email.body || '');  const combined = subj + ' ' + body;  // Evite / Event invitation & RSVP  if (/invitation|invite|evite|rsvp|you('re| are) invited/.test(combined)) {    let status = 'received';    if (/accepted|yes.*attend|will attend|confirmed|going|attending/.test(combined)) status = 'accepted';    else if (/declined|no.*attend|cannot attend|won.t be|not attend|regret/.test(combined)) status = 'declined';    else if (/maybe|tentative|might|possibly/.test(combined)) status = 'maybe';    // Extract event name from subject    const eventMatch = (email.subject || '').match(/invitation:?\s*(.+?)(?:\s*@|\s*on\s|\s*-\s*\d|$)/i);    const eventName = eventMatch ? eventMatch[1].trim() : (email.subject || '').substring(0, 60);    return { type: 'evite', status, eventName };  }  // Magazine / Jagriti article submission  if (/jagriti|spandan|magazine|article|story|poem|essay|sketch|painting|contribut|submission|submit/.test(combined)) {    return { type: 'article_submission' };  }  // Volunteer / volunteer work  if (/volunteer|help.*organiz|organiz.*help|set.?up|clean.?up|coordin|assist ing|helping out|drove|picked up|managed|hosted|facilitate/.test(combined)) {    return { type: 'volunteer' };  }  // GBM / meeting minutes / governance  if (/gbm|general body|meeting|minutes|agenda|election|vote|resolution/.test(combined)) {    return { type: 'governance' };  }  // Payment / financial  if (/payment|paid|zelle|venmo|check|dues|membership fee|receipt/.test(combined)) {    return { type: 'payment' };  }  return { type: 'general' };}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// Gravatar photo lookup (uses email hash)// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function getGravatarUrl(email) {  if (!email) return null;  const hash = crypto.createHash('md5').update(email.toLowerCase().trim()).digest('hex');  const url = `https://www.gravatar.com/avatar/${hash}?s=200&d=404`;  try {    const res = await fetch(url);    if (res.ok && res.headers.get('content-type')?.includes('image')) return url;  } catch (_) {}  return null;}/** Try DuckDuckGo image search for person photo */async function searchWebPhoto(fullName, city, org) {  const query = encodeURIComponent(`"${fullName}" ${org || 'BANF'} ${city || 'Jacksonville'} site:linkedin.com OR site:facebook.com`);  // Return LinkedIn search URL (for display in report) since scraping is unreliable  return `https://www.linkedin.com/search/results/people/?keywords=${encodeURIComponent(fullName)}`;}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// XLSX scanner ΓÇö uses STRICT name matching (no bare-surname matches)// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇfunction scanAllXLSX(dataDir, firstName, lastName, aliases = []) {  const results = {    magazineContributions: [],  // from Jagriti sheets (member + family)    membershipHistory: [],       // from Family Universe / Raw Entries    eventParticipation: [],      // from any event XLSX    advertisements: [],          // magazine ad sponsors    culturalParticipation: [],   // cultural event involvement  };  const xlsxFiles = walkDir(dataDir, ['.xlsx', '.xls']);  for (const fp of xlsxFiles) {    let wb;    try { wb = XLSX.readFile(fp, { cellDates: true }); } catch (_) { continue; }    const filename = path.basename(fp);    for (const sheetName of wb.SheetNames) {      let rows;      try { rows = XLSX.utils.sheet_to_json(wb.Sheets[sheetName], { defval: '' }); } catch (_) { continue; }      for (const row of rows) {        const rowStr = JSON.stringify(row);        // Use STRICT mentionsName ΓÇö will NOT match on bare "Ghosh"        if (!mentionsName(rowStr, firstName, lastName, aliases)) continue;        // Jagriti contribution sheets        if (/jagriti/i.test(filename) && /contribution/i.test(sheetName)) {          const comments = row['Comments'] || row['__EMPTY'] || row['Notes'] || '';          const contributor = row['Contributor'] || row['Name'] || '';          // Check if this is the member directly or a family member's contribution          const isDirect = mentionsName(contributor, firstName, lastName, aliases);          const isFamilyRef = !isDirect && norm(comments).includes(norm(firstName));          results.magazineContributions.push({            magazine: filename.replace('.xlsx','').replace('.xls',''),            contributor,            type: row['Type'] || '',            count: row['Count'] || '',            notes: comments,            sentTo: row['Sent to location'] || '',            source: `${filename} / ${sheetName}`,            relationship: isDirect ? 'Self' : (isFamilyRef ? `Family (${comments.substring(0,50)})` : 'Related')          });        }        // Jagriti ad sheets        else if (/jagriti/i.test(filename) && /advertisement/i.test(sheetName)) {          results.advertisements.push({            magazine: filename.replace('.xlsx',''),            name: row['Name'] || '',            adReceived: row['Ad Recd (Y/N)'] || '',            page: row['Page'] || '',            source: `${filename} / ${sheetName}`          });        }        // Family Universe ΓÇö Raw Entries        else if (/family/i.test(filename) && /raw/i.test(sheetName)) {          results.membershipHistory.push({            year: row['Year'] || '',            entry: row['Name Entry'] || row['Name'] || '',            type: row['Membership Type'] || '',            source: row['Source'] || `${filename} / ${sheetName}`          });        }        // Family Universe ΓÇö Yearly Membership        else if (/family/i.test(filename) && /yearly/i.test(sheetName)) {          const years = [];          for (const [k, v] of Object.entries(row)) {            if (/20\d\d/.test(k)) {              const val = String(v || '').toLowerCase().trim();              const active = ['Γ£ô','yes','y','x','true','1'].includes(val);              if (active) years.push(k);            }          }          if (years.length) results.membershipHistory.push({            year: years.join(', '),            entry: row['Members'] || row['Primary Surname'] || '',            type: 'Yearly Membership',            source: `${filename} / ${sheetName}`,            familyId: row['Family ID'] || ''          });        }        // Membership payment XLSX        else if (/membership/i.test(filename)) {          results.eventParticipation.push({            file: filename, sheet: sheetName,            rowData: Object.fromEntries(              Object.entries(row).filter(([k, v]) => String(v).trim() !== '')            )          });        }        // Any other XLSX ΓÇö cultural/event participation        else {          const entry = {            file: filename, sheet: sheetName,            rowData: Object.fromEntries(              Object.entries(row).filter(([k, v]) => String(v).trim() !== '')            )          };          // Classify as cultural if event-related          if (/puja|holi|borsho|picnic|sport|camp|mahalaya|saraswati|trijoy|cultural/i.test(filename + sheetName)) {            results.culturalParticipation.push(entry);          } else {            results.eventParticipation.push(entry);          }        }      }    }  }  // Deduplicate membership history  const seen = new Set();  results.membershipHistory = results.membershipHistory.filter(r => {    const k = r.year + '|' + r.entry;    if (seen.has(k)) return false;    seen.add(k); return true;  });  return results;}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// PDF scanner ΓÇö searches all PDFs for member name mentions// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function scanAllPDFs(dataDir, firstName, lastName, aliases = []) {  const results = {    volunteerMentions: [],    magazineArticles: [],    eventMentions: [],    governanceMentions: [],  };  const pdfFiles = walkDir(dataDir, ['.pdf']);  console.log(`  ≡ƒôä Scanning ${pdfFiles.length} PDF files for "${firstName} ${lastName}"...`);  for (const fp of pdfFiles) {    let text = '';    try {      const buf = fs.readFileSync(fp);      text = extractPdfText(buf);    } catch (_) { continue; }    const chars = text.length;    if (chars < 20) continue; // skip unreadable PDFs silently    const hasName = mentionsName(text, firstName, lastName, aliases);    if (!hasName) continue;    const filename = path.basename(fp);    const fileLower = filename.toLowerCase();    // Extract sentences/lines containing the name    const sentences = text.split(/[.!?\n]/).filter(s =>      mentionsName(s, firstName, lastName, aliases) && s.trim().length > 10    ).map(s => s.replace(/\s+/g, ' ').trim()).slice(0, 5);    const entry = { file: filename, excerpts: sentences };    if (/spandan|jagriti|magazine|newsletter/i.test(fileLower)) {      results.magazineArticles.push(entry);    } else if (/volunteer|social|welfare|camp|food|drive|service/i.test(fileLower)) {      results.volunteerMentions.push(entry);    } else if (/gbm|minutes|meeting|agenda|election/i.test(fileLower)) {      results.governanceMentions.push(entry);    } else {      results.eventMentions.push(entry);    }  }  return results;}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// Format date helpers// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇfunction fmtDate(d) {  if (!d) return 'ΓÇö';  try { return new Date(d).toLocaleDateString('en-US', { year:'numeric', month:'short', day:'numeric' }); }  catch (_) { return String(d); }}function fmtDateTime(d) {  if (!d) return 'ΓÇö';  try { return new Date(d).toLocaleString('en-US', { year:'numeric', month:'short', day:'numeric', hour:'2-digit', minute:'2-digit' }); }  catch (_) { return String(d); }}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// HTML generator// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇfunction buildHTML(data) {  const { member, profile, payments, comms, roles, awards, volunteer,          xlsxData, pdfData, evites, articles, photoUrl, linkedinUrl,          generated } = data;  const fullName = member.displayName || `${member.firstName || ''} ${member.lastName || ''}`.trim();  const initials = [member.firstName, member.lastName].map(n => (n||'')[0]).filter(Boolean).join('').toUpperCase();  // Payment summary  const totalPaid = payments.reduce((s, p) => s + (parseFloat(p.amount) || 0), 0);  const payYears = [...new Set(payments.map(p => p.membershipYear).filter(Boolean))].sort().reverse();  // Evite summary  const eviteAccepted  = evites.filter(e => e.status === 'accepted').length;  const eviteDeclined  = evites.filter(e => e.status === 'declined').length;  const evitePending   = evites.filter(e => e.status === 'received' || e.status === 'maybe').length;  // Magazine summary  const allArticles = [    ...xlsxData.magazineContributions,    ...pdfData.magazineArticles.map(p => ({ magazine: p.file, type: 'Mention in PDF', notes: p.excerpts.join('; '), source: p.file })),    ...articles  ];  // Volunteer summary  const volunteerSources = [    ...volunteer.records.map(v => ({ source: 'CRM', activity: v.activity || v.description || '', date: v.date, hours: v.hours || 0 })),    ...pdfData.volunteerMentions.map(p => ({ source: p.file, activity: p.excerpts.join('; '), date: '', hours: 0 }))  ];  // Communications by type  const commsByType = {};  for (const c of comms) {    const cls = classifyEmail(c);    if (!commsByType[cls.type]) commsByType[cls.type] = [];    commsByType[cls.type].push({ ...c, _classification: cls });  }  // CSS  const css = `  <style>  :root{--c-banf:#1a2e5a;--c-gold:#c9a84c;--c-ok:#16a34a;--c-warn:#d97706;--c-err:#dc2626;--c-info:#3b82f6;--bg:#f0f4f8;--card:#fff;--border:#dde3ed}  *{box-sizing:border-box;margin:0;padding:0}  body{font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif;background:var(--bg);color:#1e293b;font-size:14px;line-height:1.5}  .page{max-width:1100px;margin:0 auto;padding:24px}  /* Header */  .hero{background:linear-gradient(135deg,var(--c-banf) 0%,#2d4a8a 100%);border-radius:16px;padding:36px;display:flex;gap:28px;align-items:center;color:#fff;margin-bottom:28px}  .avatar{width:100px;height:100px;border-radius:50%;border:3px solid var(--c-gold);overflow:hidden;flex-shrink:0;background:#fff;display:flex;align-items:center;justify-content:center;font-size:2.4rem;font-weight:700;color:var(--c-banf)}  .avatar img{width:100%;height:100%;object-fit:cover}  .hero-info h1{font-size:2rem;font-weight:700;margin-bottom:4px}  .hero-info .tagline{color:#b8cef8;font-size:.9rem;margin-bottom:12px}  .hero-badges{display:flex;gap:8px;flex-wrap:wrap}  .hbadge{background:rgba(255,255,255,.15);padding:4px 12px;border-radius:20px;font-size:.78rem;border:1px solid rgba(255,255,255,.25)}  .hbadge.gold{background:rgba(201,168,76,.25);border-color:var(--c-gold);color:var(--c-gold)}  .hero-right{margin-left:auto;text-align:right}  .photo-links a{color:#b8cef8;font-size:.78rem;text-decoration:underline;display:block}  /* Stat cards */  .statgrid{display:grid;grid-template-columns:repeat(auto-fit,minmax(140px,1fr));gap:12px;margin-bottom:28px}  .stat{background:var(--card);border-radius:10px;padding:16px;text-align:center;border:1px solid var(--border);box-shadow:0 1px 3px #0001}  .stat .num{font-size:2rem;font-weight:700;line-height:1.1}  .stat .lbl{font-size:.72rem;color:#64748b;margin-top:3px;text-transform:uppercase;letter-spacing:.03em}  .stat.blue .num{color:var(--c-info)} .stat.green .num{color:var(--c-ok)} .stat.amber .num{color:var(--c-warn)} .stat.red .num{color:var(--c-err)} .stat.gold .num{color:var(--c-gold)}  /* Sections */  .section{background:var(--card);border-radius:12px;padding:22px;margin-bottom:20px;border:1px solid var(--border);box-shadow:0 1px 4px #0001}  .section-title{font-size:1.05rem;font-weight:700;color:var(--c-banf);border-bottom:2px solid var(--border);padding-bottom:8px;margin-bottom:16px;display:flex;align-items:center;gap:8px}  .section-title span{font-size:1.2rem}  .source-tag{display:inline-block;background:#f1f5f9;border:1px solid #cdd5e0;padding:1px 6px;border-radius:4px;font-size:.68rem;color:#475569;margin-left:4px;vertical-align:middle}  /* Tables */  table{width:100%;border-collapse:collapse;font-size:.83rem}  th{background:#f8fafc;color:#374151;font-weight:600;padding:9px 12px;text-align:left;border-bottom:2px solid var(--border)}  td{padding:8px 12px;border-bottom:1px solid #f1f5f9;vertical-align:top}  tr:last-child td{border-bottom:none}  tr:hover td{background:#f8fbff}  /* Badges */  .badge{display:inline-block;padding:2px 9px;border-radius:99px;font-size:.7rem;font-weight:600}  .badge.ok{background:#d1fae5;color:#065f46} .badge.warn{background:#fef3c7;color:#92400e}  .badge.err{background:#fee2e2;color:#991b1b} .badge.info{background:#dbeafe;color:#1d4ed8}  .badge.gold{background:#fef9c3;color:#854d0e} .badge.grey{background:#f1f5f9;color:#475569}  .badge.purple{background:#ede9fe;color:#5b21b6}  /* Timeline */  .timeline{list-style:none}  .timeline li{padding:10px 0 10px 24px;border-left:2px solid var(--border);position:relative;margin-left:8px}  .timeline li::before{content:'';position:absolute;left:-5px;top:15px;width:8px;height:8px;border-radius:50%;background:var(--c-banf);border:2px solid #fff;box-shadow:0 0 0 2px var(--c-banf)}  .timeline li.current::before{background:var(--c-gold)}  .tl-date{font-size:.72rem;color:#94a3b8;margin-bottom:2px}  .tl-title{font-weight:600;color:#1e293b}  .tl-sub{font-size:.8rem;color:#475569;margin-top:2px}  /* Email thread */  .email-item{border:1px solid var(--border);border-radius:8px;padding:12px 14px;margin-bottom:8px}  .email-item:hover{border-color:#a5b4fc}  .email-header{display:flex;align-items:flex-start;justify-content:space-between;gap:8px;margin-bottom:4px}  .email-subj{font-weight:600;font-size:.85rem;color:#1e293b}  .email-meta{font-size:.72rem;color:#94a3b8;white-space:nowrap}  .email-body{font-size:.78rem;color:#475569;margin-top:4px;padding-top:6px;border-top:1px solid #f1f5f9}  /* Evite cards */  .evite-grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(220px,1fr));gap:10px}  .evite-card{border:1px solid var(--border);border-radius:8px;padding:14px}  .evite-card.accepted{border-color:#86efac;background:#f0fdf4}  .evite-card.declined{border-color:#fca5a5;background:#fff5f5}  .evite-card.maybe{border-color:#fcd34d;background:#fffbeb}  .evite-card.received{border-color:#bfdbfe;background:#eff6ff}  .evite-name{font-weight:600;font-size:.85rem;margin-bottom:6px}  .evite-date{font-size:.72rem;color:#64748b;margin-bottom:4px}  /* Article cards */  .contrib-card{border-left:3px solid var(--c-gold);padding:10px 14px;background:#fffdf5;margin-bottom:8px;border-radius:0 6px 6px 0}  .contrib-title{font-weight:600;font-size:.88rem}  .contrib-sub{font-size:.76rem;color:#64748b;margin-top:2px}  .contrib-notes{font-size:.78rem;color:#475569;margin-top:4px;font-style:italic}  /* Two column layout */  .two-col{display:grid;grid-template-columns:1fr 1fr;gap:20px}  @media(max-width:700px){.two-col{grid-template-columns:1fr}.hero{flex-direction:column}}  /* No-data */  .empty{color:#94a3b8;font-size:.82rem;font-style:italic;padding:8px 0}  /* Footer */  .footer{text-align:center;color:#94a3b8;font-size:.75rem;margin-top:32px;padding:12px}  .data-source{background:#f8fafc;border:1px solid var(--border);border-radius:6px;padding:8px 12px;font-size:.74rem;color:#475569;margin-bottom:12px}  .data-source strong{color:#374151}  </style>`;  // Helper: render excerpts  function renderExcerpts(excerpts) {    if (!excerpts || !excerpts.length) return '<em class="empty">No text excerpts extracted.</em>';    return excerpts.map(e => `<div class="email-body">${esc(e)}</div>`).join('');  }  // ΓöÇΓöÇΓöÇ Section: Profile ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  const profileSection = `  <div class="two-col">    <div class="section">      <div class="section-title"><span>≡ƒæñ</span> Member Profile <small class="source-tag">CRM API</small></div>      <table>        <tr><th>Field</th><th>Value</th></tr>        <tr><td>Member ID</td><td>${esc(member.memberId)}</td></tr>        <tr><td>Family ID</td><td>${esc(member.familyId)}</td></tr>        <tr><td>Email</td><td>${esc(member.email)}</td></tr>        ${member.alternateEmail ? `<tr><td>Alt Email</td><td>${esc(member.alternateEmail)}</td></tr>` : ''}        <tr><td>Phone</td><td>${esc(member.phone) || 'ΓÇö'}</td></tr>        <tr><td>Location</td><td>${[profile.city, profile.state].filter(Boolean).join(', ') || 'ΓÇö'}</td></tr>        <tr><td>Member Since</td><td>${esc(member.memberSince) || 'ΓÇö'}</td></tr>        <tr><td>Family Type</td><td>${esc(member.familyType) || 'ΓÇö'}</td></tr>        <tr><td>Status</td><td><span class="badge ${member.isActive ? 'ok' : 'err'}">${member.isActive ? 'Active' : 'Inactive'}</span></td></tr>        <tr><td>EC Member</td><td>${profile.isECMember ? '<span class="badge gold">Yes</span>' : 'No'}</td></tr>        <tr><td>Life Member</td><td>${member.isLifeMember ? '<span class="badge purple">Yes</span>' : 'No'}</td></tr>      </table>    </div>    <div class="section">      <div class="section-title"><span>≡ƒÆ╝</span> Professional Info <small class="source-tag">CRM API</small></div>      <table>        <tr><th>Field</th><th>Value</th></tr>        <tr><td>Profession</td><td>${esc(profile.profession) || 'ΓÇö'}</td></tr>        <tr><td>Employer</td><td>${esc(profile.employer) || 'ΓÇö'}</td></tr>        <tr><td>Education</td><td>${esc(profile.education) || 'ΓÇö'}</td></tr>        <tr><td>Skills</td><td>${esc(profile.skills) || 'ΓÇö'}</td></tr>        <tr><td>Gender</td><td>${esc(profile.gender) || 'ΓÇö'}</td></tr>        <tr><td>Date of Birth</td><td>${profile.dateOfBirth ? fmtDate(profile.dateOfBirth) : 'ΓÇö'}</td></tr>        <tr><td>Notes</td><td><em>${esc(member.notes) || 'ΓÇö'}</em></td></tr>      </table>      <br>      <div class="section-title"><span>≡ƒöù</span> Online Profiles <small class="source-tag">Web Search</small></div>      <p><a href="${esc(linkedinUrl)}" target="_blank" style="color:var(--c-info)">≡ƒöì LinkedIn Search: ${esc(fullName)}</a></p>      ${member.linkedIn ? `<p><a href="${esc(member.linkedIn)}" target="_blank" style="color:var(--c-info)">LinkedIn Profile (CRM)</a></p>` : ''}      ${photoUrl ? `<p style="margin-top:8px"><img src="${photoUrl}" alt="Profile photo" style="width:60px;height:60px;border-radius:50%;border:2px solid var(--border)"></p>` : '<p class="empty">No profile photo found via Gravatar.</p>'}    </div>  </div>`;  // ΓöÇΓöÇΓöÇ Section: Family Unit (co-occurrence based) ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  const familyUnit = xlsxData.familyUnit || [];  const familyRows = familyUnit.length    ? familyUnit.map(f => `        <tr>          <td><strong>${esc(f.name)}</strong></td>          <td><span class="badge ${f.confidence === 'high' ? 'ok' : f.confidence === 'medium' ? 'warn' : 'info'}">${esc(f.relationship)}</span></td>          <td><span class="badge ${f.confidence === 'high' ? 'ok' : f.confidence === 'medium' ? 'warn' : 'grey'}">${esc(f.confidence)}</span></td>          <td><small class="source-tag">${esc(f.source)}</small></td>        </tr>`).join('')    : `<tr><td colspan="4" class="empty">No co-occurrence family data found in documents.</td></tr>`;  const familySection = `  <div class="section">    <div class="section-title"><span>≡ƒæ¿ΓÇì≡ƒæ⌐ΓÇì≡ƒæºΓÇì≡ƒæª</span> Family Unit <small class="source-tag">Document Co-occurrence Analysis</small></div>    <p style="margin-bottom:10px;font-size:.82rem;color:#475569">      Family members identified by analyzing names that appear together in payment entries, membership rolls, and magazine contributor comments.      <strong>Not</strong> based on surname matching.    </p>    <table>      <tr><th>Name</th><th>Relationship</th><th>Confidence</th><th>Evidence Source</th></tr>      ${familyRows}    </table>  </div>`;  // ΓöÇΓöÇΓöÇ Section: Membership History ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  const histRows = xlsxData.membershipHistory.length    ? xlsxData.membershipHistory.map(h => `        <tr>          <td>${esc(h.year)}</td>          <td>${esc(h.entry)}</td>          <td>${esc(h.type)}</td>          <td><small class="source-tag">${esc(h.source)}</small></td>        </tr>`).join('')    : `<tr><td colspan="4" class="empty">No historical XLSX records found for this member.</td></tr>`;  const histSection = `  <div class="section">    <div class="section-title"><span>≡ƒôà</span> Membership History <small class="source-tag">Family Universe XLSX + Membership XLSX</small></div>    <table>      <tr><th>Year(s)</th><th>Name Entry in Document</th><th>Category / Type</th><th>Source Document</th></tr>      ${histRows}    </table>  </div>`;  // ΓöÇΓöÇΓöÇ Section: Payments ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  let payRows = '';  if (payments.length) {    payRows = payments.map(p => `      <tr>        <td>${esc(p.membershipYear) || 'ΓÇö'}</td>        <td><strong>$${(p.amount||0).toFixed(2)}</strong></td>        <td>${esc(p.membershipType) || 'ΓÇö'}</td>        <td>${esc(p.familyType) || 'ΓÇö'}</td>        <td>${p.earlyBird ? '<span class="badge gold">Early Bird</span>' : '<span class="badge grey">Standard</span>'}</td>        <td>${esc(p.paymentMethod) || 'ΓÇö'}</td>        <td><span class="badge ${p.status === 'paid' ? 'ok' : 'warn'}">${esc(p.status) || 'ΓÇö'}</span></td>        <td>${fmtDate(p.paymentDate)}</td>        <td><small>${esc(p.rawNameEntry) || esc(p.notes) || 'ΓÇö'}</small><br><small class="source-tag">${esc(p.importSource) || 'CRM'}</small></td>      </tr>`).join('');  } else {    payRows = '<tr><td colspan="9" class="empty">No payment records in CRM database. Check XLSX source documents.</td></tr>';  }  const paySection = `  <div class="section">    <div class="section-title"><span>≡ƒÆ│</span> Full Payment History <small class="source-tag">CRM Payments API + Membership XLSX</small></div>    ${payments.length ? `<p style="margin-bottom:12px;color:#475569;font-size:.82rem">Total paid: <strong>$${totalPaid.toFixed(2)}</strong> across ${payments.length} record(s) ΓÇö Years on file: ${payYears.join(', ') || 'N/A'}</p>` : ''}    <table>      <tr><th>Year</th><th>Amount</th><th>Type</th><th>Family</th><th>Tier</th><th>Method</th><th>Status</th><th>Date</th><th>Notes / Source</th></tr>      ${payRows}    </table>  </div>`;  // ΓöÇΓöÇΓöÇ Section: Evite RSVPs ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  const eviteCards = evites.length    ? `<div class="evite-grid">` + evites.map(e => `        <div class="evite-card ${e.status}">          <div class="evite-name">${esc(e.eventName)}</div>          <div class="evite-date">${fmtDate(e.date)}</div>          <span class="badge ${e.status === 'accepted' ? 'ok' : e.status === 'declined' ? 'err' : e.status === 'maybe' ? 'warn' : 'info'}">${e.status.toUpperCase()}</span>          ${e.participants ? `<div class="contrib-notes">Participants: ${esc(e.participants)}</div>` : ''}          ${e.notes ? `<div class="contrib-notes">Notes: ${esc(e.notes)}</div>` : ''}          <div style="margin-top:6px"><small class="source-tag">${esc(e.direction === 'inbound' ? 'Member ΓåÆ BANF' : 'BANF ΓåÆ Member')}</small></div>        </div>`).join('') + `</div>`    : '<p class="empty">No evite / RSVP emails found in communications.</p>';  const eviteSection = `  <div class="section">    <div class="section-title"><span>≡ƒôº</span> Event Invitations & RSVPs <small class="source-tag">Email Communications</small></div>    <p style="margin-bottom:12px;font-size:.82rem;color:#475569">      ${evites.length} evite(s) found ΓÇö       <span class="badge ok">${eviteAccepted} Accepted</span>      <span class="badge err">${eviteDeclined} Declined</span>      <span class="badge info">${evitePending} Pending/Maybe</span>    </p>    ${eviteCards}  </div>`;  // ΓöÇΓöÇΓöÇ Section: Magazine / Jagriti Contributions ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  const articleItems = allArticles.length    ? allArticles.map(a => `        <div class="contrib-card">          <div class="contrib-title">            ${esc(a.magazine || a.file || 'Unknown Magazine')}            ${a.type ? `<span class="badge gold" style="margin-left:6px">${esc(a.type)}</span>` : ''}            ${a.count ? `<span class="badge info" style="margin-left:4px">${a.count} piece(s)</span>` : ''}            ${a.relationship ? `<span class="badge ${a.relationship === 'Self' ? 'ok' : 'purple'}" style="margin-left:4px">${esc(a.relationship)}</span>` : ''}          </div>          ${a.contributor ? `<div class="contrib-sub">Contributor: <strong>${esc(a.contributor)}</strong></div>` : ''}          ${a.sentTo ? `<div class="contrib-sub">Submitted to: ${esc(a.sentTo)}</div>` : ''}          ${a.notes ? `<div class="contrib-notes">${esc(a.notes)}</div>` : ''}          ${a.excerpts && a.excerpts.length ? `<div class="contrib-notes">PDF excerpt: ${esc(a.excerpts.join(' | '))}</div>` : ''}          <small class="source-tag" style="margin-top:4px">${esc(a.source || a.file)}</small>        </div>`).join('')    : '<p class="empty">No magazine/Jagriti contribution records found in XLSX or PDF documents.</p>';  // Article-related emails  const articleEmails = (commsByType['article_submission'] || []);  const articleEmailsHtml = articleEmails.length    ? articleEmails.map(e => `        <div class="email-item">          <div class="email-header">            <div class="email-subj">${esc(e.subject)}</div>            <div class="email-meta">${fmtDateTime(e.date)}</div>          </div>          <div class="contrib-sub">${e.direction === 'inbound' ? 'Γåæ From member' : 'Γåô To member'} ΓÇö ${esc(e.from)} ΓåÆ ${esc(e.to)}</div>          ${e.body ? `<div class="email-body">${esc(e.body.substring(0, 300))}${e.body.length > 300 ? 'ΓÇª' : ''}</div>` : ''}        </div>`).join('')    : '';  const articleSection = `  <div class="section">    <div class="section-title"><span>≡ƒô¥</span> Magazine & Article Contributions <small class="source-tag">Jagriti XLSX + Spandan PDF + Emails</small></div>    ${articleItems}    ${articleEmailsHtml ? `<div style="margin-top:12px"><strong style="font-size:.82rem;color:#475569">Related emails:</strong>${articleEmailsHtml}</div>` : ''}  </div>`;  // ΓöÇΓöÇΓöÇ Section: Volunteer Work ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  const volItems = volunteerSources.length    ? volunteerSources.map(v => `        <div class="contrib-card" style="border-color:var(--c-ok)">          <div class="contrib-title">${esc(v.activity) || 'Volunteer Activity'}</div>          ${v.date ? `<div class="contrib-sub">${fmtDate(v.date)}</div>` : ''}          ${v.hours ? `<span class="badge ok">${v.hours} hrs</span>` : ''}          <small class="source-tag">${esc(v.source)}</small>        </div>`).join('')    : '<p class="empty">No volunteer records found in CRM or PDF documents. Volunteer work may be in unscanned documents.</p>';  const govMentions = pdfData.governanceMentions.length    ? pdfData.governanceMentions.map(g => `        <div class="email-item">          <div class="email-header"><div class="email-subj">${esc(g.file)}</div></div>          ${renderExcerpts(g.excerpts)}        </div>`).join('')    : '';  const volSection = `  <div class="section">    <div class="section-title"><span>≡ƒñ¥</span> Voluntary Work <small class="source-tag">CRM Records + PDFs</small></div>    ${volItems}    ${govMentions ? `<div style="margin-top:16px"><strong style="font-size:.82rem;color:#475569">Governance document mentions:</strong>${govMentions}</div>` : ''}  </div>`;  // ΓöÇΓöÇΓöÇ Section: EC / Org Roles ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  const roleTimeline = roles.length    ? `<ul class="timeline">` + roles.map(r => `        <li class="${r.isCurrentRole ? 'current' : ''}">          <div class="tl-date">${fmtDate(r.startDate)} ΓÇö ${r.endDate ? fmtDate(r.endDate) : 'Present'}</div>          <div class="tl-title">${esc(r.roleTitle || r.roleName || 'Member')} <span class="badge ${r.isCurrentRole ? 'gold' : 'grey'}">${r.isCurrentRole ? 'Current' : 'Past'}</span></div>          <div class="tl-sub">${esc(r.orgName || 'BANF')} ┬╖ ${esc(r.orgTerm || r.term || '')} ${r.description ? '┬╖ ' + esc(r.description) : ''}</div>          <small class="source-tag">${esc(r.importSource || 'CRM')}</small>        </li>`).join('') + `</ul>`    : '<p class="empty">No organizational roles found in CRM.</p>';  const rolesSection = `  <div class="section">    <div class="section-title"><span>≡ƒÅ¢∩╕Å</span> EC / Organizational Roles <small class="source-tag">CRM MemberOrgRoles</small></div>    ${roleTimeline}  </div>`;  // ΓöÇΓöÇΓöÇ Section: All Communications ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  const commTypeLabels = {    evite: '≡ƒô¿ Evite/Invite', article_submission: '≡ƒô¥ Article/Magazine',    volunteer: '≡ƒñ¥ Volunteer', governance: '≡ƒÅ¢∩╕Å Governance/GBM',    payment: '≡ƒÆ│ Payment', general: '≡ƒÆ¼ General'  };  let allCommsHtml = '';  for (const [type, emails] of Object.entries(commsByType)) {    allCommsHtml += `<div style="margin-bottom:16px">      <strong style="font-size:.82rem;color:var(--c-banf)">${commTypeLabels[type] || type} (${emails.length})</strong>      ${emails.map(e => `        <div class="email-item" style="margin-top:6px">          <div class="email-header">            <div class="email-subj">${esc(e.subject)}</div>            <div class="email-meta">${e.direction === 'inbound' ? 'Γåæ' : 'Γåô'} ${fmtDate(e.date)}</div>          </div>          <div style="font-size:.72rem;color:#94a3b8">${esc(e.from)} ΓåÆ ${esc(e.to)}</div>          ${e.body && e.body.trim() ? `<div class="email-body">${esc(e.body.substring(0,200))}${e.body.length>200?'ΓÇª':''}</div>` : ''}        </div>`).join('')}    </div>`;  }  const commsSection = `  <div class="section">    <div class="section-title"><span>≡ƒô¼</span> All Communications (${comms.length}) <small class="source-tag">CRM MemberCommunications + Gmail Sync</small></div>    ${allCommsHtml || '<p class="empty">No communications on file.</p>'}  </div>`;  // ΓöÇΓöÇΓöÇ Section: Cultural & Event Participation ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  const culturalItems = xlsxData.culturalParticipation || [];  const pdfEvents = pdfData.eventMentions || [];  const allEventItems = [...culturalItems, ...pdfEvents];  let culturalHtml = '';  if (culturalItems.length) {    culturalHtml += culturalItems.map(c => {      const data = c.rowData || {};      const cols = Object.entries(data).map(([k,v]) => `<strong>${esc(k)}</strong>: ${esc(String(v))}`).join(' | ');      return `<div class="email-item">        <div class="email-header"><div class="email-subj">${esc(c.file)} <small class="source-tag">XLSX / ${esc(c.sheet)}</small></div></div>        <div class="email-body">${cols}</div>      </div>`;    }).join('');  }  if (pdfEvents.length) {    culturalHtml += pdfEvents.map(p => `      <div class="email-item">        <div class="email-header"><div class="email-subj">${esc(p.file)} <small class="source-tag">PDF</small></div></div>        ${renderExcerpts(p.excerpts)}      </div>`).join('');  }  const pdfSection = allEventItems.length    ? `<div class="section">        <div class="section-title"><span>≡ƒÄ¡</span> Cultural & Event Participation <small class="source-tag">XLSX + PDFs</small></div>        <p style="margin-bottom:10px;font-size:.82rem;color:#475569">${allEventItems.length} event record(s) found across documents.</p>        ${culturalHtml}      </div>`    : `<div class="section">        <div class="section-title"><span>≡ƒÄ¡</span> Cultural & Event Participation</div>        <p class="empty">No cultural or event participation records found in XLSX or PDF documents.</p>      </div>`;  // ΓöÇΓöÇΓöÇ Data Sources Panel ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  const sourcesHtml = `  <div class="data-source">    <strong>≡ƒôè Data Sources Used for This Report:</strong><br>    ΓÇó <strong>CRM API</strong>: Member profile, payments (${payments.length} records), communications (${comms.length}), org roles (${roles.length}), awards (${awards.length})<br>    ΓÇó <strong>Family Unit</strong>: ${familyUnit.length} family members detected via document co-occurrence (not surname matching)<br>    ΓÇó <strong>XLSX Files Scanned</strong>: ${walkDir(DATA_ROOT, ['.xlsx','.xls']).length} files ΓåÆ ${xlsxData.membershipHistory.length} membership history records, ${xlsxData.magazineContributions.length} magazine contributions, ${(xlsxData.culturalParticipation||[]).length} cultural events<br>    ΓÇó <strong>PDF Files Scanned</strong>: ${walkDir(DATA_ROOT, ['.pdf']).length} files ΓåÆ ${pdfData.eventMentions.length} event mentions, ${pdfData.volunteerMentions.length} volunteer mentions, ${pdfData.governanceMentions.length} governance mentions<br>    ΓÇó <strong>Web</strong>: Gravatar (email hash lookup), LinkedIn search URL generated<br>    ΓÇó <strong>Generated</strong>: ${generated}  </div>`;  // ΓöÇΓöÇΓöÇ Awards & Recognition ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  const awardsSection = `  <div class="section">    <div class="section-title"><span>≡ƒÅå</span> Awards & Recognition <small class="source-tag">CRM MemberAwards</small></div>    ${awards.length ? `<table>      <tr><th>Award</th><th>Year</th><th>Description</th><th>Notes</th></tr>      ${awards.map(a => `<tr><td>${esc(a.awardName||a.name||'')}</td><td>${esc(a.year||a.awardYear||'')}</td><td>${esc(a.description||'')}</td><td>${esc(a.notes||'')}</td></tr>`).join('')}    </table>` : '<p class="empty">No awards or recognition records found in CRM. Awards data may be recorded in event documents or meeting minutes.</p>'}  </div>`;  // ΓöÇΓöÇΓöÇ Full HTML ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ  return `<!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>BANF Member Report ΓÇö ${esc(fullName)}</title>${css}</head><body><div class="page">  <!-- HERO -->  <div class="hero">    <div class="avatar">${photoUrl ? `<img src="${photoUrl}" alt="${esc(fullName)}" onerror="this.parentElement.textContent='${esc(initials)}'">` : esc(initials)}</div>    <div class="hero-info">      <h1>${esc(fullName)}</h1>      <div class="tagline">        ${[profile.city, profile.state].filter(Boolean).join(', ') || ''}        ${profile.employer ? ` ┬╖ ${esc(profile.employer)}` : ''}        ${profile.profession ? ` ┬╖ ${esc(profile.profession)}` : ''}      </div>      <div class="hero-badges">        <span class="hbadge">Member since ${esc(member.memberSince) || 'N/A'}</span>        ${profile.isECMember ? '<span class="hbadge gold">EC Member</span>' : ''}        ${member.isLifeMember ? '<span class="hbadge gold">Life Member</span>' : ''}        ${member.isActive ? '<span class="hbadge">Active</span>' : '<span class="hbadge">Inactive</span>'}        <span class="hbadge">${payments.length} payment(s) on file</span>        <span class="hbadge">${allArticles.length} contribution(s)</span>        <span class="hbadge">${evites.length} evite(s)</span>      </div>    </div>    <div class="hero-right">      <div class="photo-links">        <a href="${esc(linkedinUrl)}" target="_blank">≡ƒöì LinkedIn Search</a>        ${member.email ? `<a href="https://www.gravatar.com/avatar/${crypto.createHash('md5').update((member.email||'').toLowerCase()).digest('hex')}?s=200" target="_blank">≡ƒæñ Gravatar</a>` : ''}      </div>      <br>      <small style="color:#8aa4d4">Report: ${generated}</small>    </div>  </div>  <!-- STAT CARDS -->  <div class="statgrid">    <div class="stat blue"><div class="num">${payments.length}</div><div class="lbl">Payments</div></div>    <div class="stat gold"><div class="num">$${totalPaid.toFixed(0)}</div><div class="lbl">Total Paid</div></div>    <div class="stat green"><div class="num">${eviteAccepted}</div><div class="lbl">Events Accepted</div></div>    <div class="stat amber"><div class="num">${eviteDeclined + evitePending}</div><div class="lbl">Declined/Pending</div></div>    <div class="stat gold"><div class="num">${allArticles.length}</div><div class="lbl">Contributions</div></div>    <div class="stat green"><div class="num">${familyUnit.length}</div><div class="lbl">Family Members</div></div>    <div class="stat blue"><div class="num">${volunteerSources.length}</div><div class="lbl">Volunteer Records</div></div>    <div class="stat blue"><div class="num">${roles.length}</div><div class="lbl">EC/Org Roles</div></div>    <div class="stat blue"><div class="num">${comms.length}</div><div class="lbl">Emails</div></div>  </div>  ${sourcesHtml}  <!-- PROFILE + PROFESSIONAL -->  ${profileSection}  <!-- FAMILY UNIT -->  ${familySection}  <!-- MEMBERSHIP HISTORY -->  ${histSection}  <!-- PAYMENTS -->  ${paySection}  <!-- EC ROLES -->  ${rolesSection}  <!-- EVITE RSVPs -->  ${eviteSection}  <!-- MAGAZINE CONTRIBUTIONS -->  ${articleSection}  <!-- VOLUNTARY WORK -->  ${volSection}  ${awardsSection}  <!-- EVENT PARTICIPATION (PDFs) -->  ${pdfSection}  <!-- ALL COMMUNICATIONS -->  ${commsSection}  <div class="footer">    Generated by BANF Member Report Generator v3.0 ┬╖ ${generated}<br>    All data sourced from CRM API, local XLSX documents, PDF text extraction, and web search.    No values were hardcoded in this report.  </div></div></body></html>`;}// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇ// MAIN// ΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇΓöÇasync function main() {  console.log('\n≡ƒôï BANF Member Report Generator v3.0');  console.log('   Mode: fully data-driven ΓÇö co-occurrence family detection\n');  // 1. Resolve member  let memberId = TARGET_MEMBER_ID;  if (!memberId) {    console.log(`≡ƒöì Searching for member: "${TARGET_NAME}"...`);    const found = await findMemberByName(TARGET_NAME);    if (!found) { console.error('  Γ¥î Member not found.'); process.exit(1); }    memberId = found.memberId;    console.log(`   Γ£ö Found: ${found.displayName} (${memberId})`);  }  // 2. Fetch full profile from CRM API  console.log(`\n≡ƒôí Fetching CRM data for ${memberId}...`);  const [reportData, payData] = await Promise.all([    apiGet('crm_member_report', { memberId }),    apiGet('crm_member_payments', { memberId })  ]);  if (!reportData.success) throw new Error('Member report API failed: ' + JSON.stringify(reportData));  const R = reportData.report;  const member    = R.member;  const profile   = { ...R.professional, ...R.personal, isECMember: R.orgInvolvement.isECMember, isBOTMember: R.orgInvolvement.isBOTMember };  const payments  = payData.payments || [];  const comms     = R.communications.recent || [];  const roles     = R.orgInvolvement.roles || [];  const awards    = R.recognition.awards || [];  const volunteer = R.volunteer || { records: [], totalHours: 0 };  const firstName = member.firstName || (member.name || '').split(' ')[0];  const lastName  = member.lastName  || (member.name || '').split(' ').slice(1).join(' ');  const fullName  = member.displayName || `${firstName} ${lastName}`.trim();  console.log(`   Γ£ö Profile: ${fullName} | ${member.email}`);  console.log(`   Γ£ö Payments: ${payments.length} | Communications: ${comms.length} | Roles: ${roles.length}`);  // 2b. Build SMART name aliases (co-occurrence based, not bare surname)  const xlsxFiles = walkDir(DATA_ROOT, ['.xlsx', '.xls']);  const aliases = buildAliases(member, xlsxFiles);  console.log(`   Γ£ö Aliases built: ${aliases.length} ΓåÆ ${aliases.join(' | ')}`);  // 2c. Detect REAL family unit from document co-occurrence  const familyUnit = detectFamilyUnit(firstName, lastName, xlsxFiles);  console.log(`   Γ£ö Family unit: ${familyUnit.length} member(s) detected`);  familyUnit.forEach(f => console.log(`     ΓÇô ${f.name} (${f.relationship}, confidence: ${f.confidence}, src: ${f.source})`));  // 3. Scan local documents with STRICT matching  console.log('\n≡ƒôé Scanning local documents with strict name matching...');  const xlsxData = scanAllXLSX(DATA_ROOT, firstName, lastName, aliases);  xlsxData.familyUnit = familyUnit; // attach for HTML rendering  console.log(`   Γ£ö XLSX: ${xlsxData.magazineContributions.length} magazine, ${xlsxData.membershipHistory.length} membership history, ${xlsxData.eventParticipation.length} events, ${xlsxData.culturalParticipation.length} cultural`);  const pdfData = await scanAllPDFs(DATA_ROOT, firstName, lastName, aliases);  console.log(`   Γ£ö PDFs: ${pdfData.eventMentions.length} event mentions, ${pdfData.volunteerMentions.length} volunteer, ${pdfData.governanceMentions.length} governance`);  // 4. Classify communications ΓÇö parse evites, articles, volunteer refs  const evites = [];  const articles = [];  const volunteerEmails = [];  const governanceEmails = [];  for (const c of comms) {    const cls = classifyEmail(c);    if (cls.type === 'evite') {      evites.push({        eventName: cls.eventName || c.subject || 'Event',        status: cls.status,        date: c.date,        direction: c.direction,        notes: c.body ? c.body.substring(0, 200) : '',        participants: '',        subject: c.subject || ''      });    } else if (cls.type === 'article_submission') {      articles.push({        magazine: 'Email submission',        source: `Email: ${c.subject}`,        notes: c.body ? c.body.substring(0, 150) : '',        date: c.date      });    } else if (cls.type === 'volunteer') {      volunteerEmails.push(c);    } else if (cls.type === 'governance') {      governanceEmails.push(c);    }  }  console.log(`   Γ£ö Classified: ${evites.length} evites, ${articles.length} articles, ${volunteerEmails.length} volunteer, ${governanceEmails.length} governance`);  // 5. Photo / LinkedIn lookup  console.log('\n≡ƒîÉ Looking up online presence...');  const gravatarUrl = await getGravatarUrl(member.email);  if (member.alternateEmail && !gravatarUrl) await getGravatarUrl(member.alternateEmail);  const linkedinUrl = await searchWebPhoto(fullName, profile.city, 'BANF Jacksonville');  console.log(`   Γ£ö Gravatar: ${gravatarUrl ? 'found' : 'not found'} | LinkedIn search URL: generated`);  // 6. Generate HTML  const generated = new Date().toLocaleString('en-US', { year:'numeric', month:'short', day:'numeric', hour:'2-digit', minute:'2-digit' });  const htmlContent = buildHTML({    member, profile, payments, comms, roles, awards, volunteer,    xlsxData, pdfData, evites, articles,    photoUrl: gravatarUrl,    linkedinUrl,    generated  });  // 7. Save  const safeName = fullName.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/-+/g, '-');  const outFile = ARGS.out || path.join(__dirname, `member-report-${safeName}.html`);  fs.writeFileSync(outFile, htmlContent, 'utf8');  console.log(`\nΓ£à Report saved: ${outFile}`);  console.log(`   Sections included:`);  console.log(`     ΓÇó Profile + Professional info (CRM API)`);  console.log(`     ΓÇó Family unit (${familyUnit.length} members via co-occurrence, NOT surname matching)`);  console.log(`     ΓÇó Membership history (${xlsxData.membershipHistory.length} records across XLSX files)`);  console.log(`     ΓÇó Payment history (${payments.length} CRM records)`);  console.log(`     ΓÇó Evite RSVPs (${evites.length} from email classification)`);  console.log(`     ΓÇó Magazine contributions (${xlsxData.magazineContributions.length} Jagriti + ${pdfData.magazineArticles.length} PDF)`);  console.log(`     ΓÇó Cultural/Event participation (${(xlsxData.culturalParticipation||[]).length} XLSX + ${pdfData.eventMentions.length} PDF)`);  console.log(`     ΓÇó Voluntary work (${volunteer.records.length} CRM + ${pdfData.volunteerMentions.length} PDF mentions)`);  console.log(`     ΓÇó Awards & Recognition (${awards.length} CRM)`);  console.log(`     ΓÇó EC/Org roles (${roles.length})`);  console.log(`     ΓÇó All communications (${comms.length})`);  console.log(`     ΓÇó LinkedIn search URL + Gravatar photo\n`);}main().catch(e => { console.error('Fatal:', e.message); process.exit(1); });